SINA_SMART["term1-repro"] = {"lecture":"term1-repro","title":"Reproductive system terminology","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"term1-repro:e0","text":"Perineum: between pubic symphysis and coccyx.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"term1-repro:e8","text":"Urologist: male genitourinary + female urinary; obstetrician: pregnancy and birth.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"term1-repro:e1","text":"Testis: orch/o, orchid/o, test/i; penis: pen/i, phall/i.","topic":"Structures and combining forms","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"term1-repro:e2","text":"Ovary: oophor/o, ovari/o; tube: salping/o; uterus: hyster/o, metr/o, uter/o; vagina: vagin/o, colp/o.","topic":"Structures and combining forms","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"term1-repro:e3","text":"Uterine layers: perimetrium, myometrium, endometrium.","topic":"Structures and combining forms","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"term1-repro:e4","text":"-gravida pregnant; -para give birth; nulligravida vs nullipara.","topic":"Structures and combining forms","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"term1-repro:e5","text":"men/o menstruation: menarche, oligomenorrhea, menometrorrhagia.","topic":"Terms to know","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"term1-repro:e6","text":"mast/o breast: mastalgia, mastopexy (-pexy = fixation).","topic":"Terms to know","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"term1-repro:e7","text":"Orchiopexy fixes an undescended testis; oophorectomy removes an ovary.","topic":"Terms to know","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"9dup56":"a","1ujrb1w":"a","1ngf2lv":"a","16a5frc":"a","iqyjo9":"a","qcqk9p":"a","fue32v":"a","x1z3p4":"a","1u8lath":"a","11c1xvm":"a","pt0rb8":"a","1jprl1p":"a","1ch1obh":"a","1k92lxj":"a","1e769zn":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"term1-repro:e0":{"s":0,"u":["Perineum: between pubic symphysis and coccyx.","The perineum is the surface region between the pubic symphysis and the coccyx."],"dp":[]},"term1-repro:e8":{"s":0,"u":["Urologist: male genitourinary + female urinary; obstetrician: pregnancy and birth.","A urologist treats the male genitourinary and female urinary systems (ur = urine); an obstetrician cares for pregnancy and birth.","The male system produces sperm and delivers them so that one can unite with an ovum; some male structures also belong to the urinary system."],"dp":[]},"term1-repro:e1":{"s":1,"u":["Testis: orch/o, orchid/o, test/i; penis: pen/i, phall/i.","Male : penis ( pen/i, phall/i ); testicles ( orch/o, orchid/o, test/i, test/o ): produce sperm and testosterone; scrotum, epididymis, vas deferens, seminal vesicles, ejaculatory duct, prostate, bulbourethral glands, urethra, seminiferous tubules."],"dp":[]},"term1-repro:e2":{"s":1,"u":["Ovary: oophor/o, ovari/o; tube: salping/o; uterus: hyster/o, metr/o, uter/o; vagina: vagin/o, colp/o.","Female : ovaries ( oophor/o, ovari/o ): ova and hormones; fallopian tubes ( salping/o ): catch the ovum, site of fertilisation; uterus ( hyster/o, metr/o, metri/o, uter/o ): protects the developing child; vagina ( vagin/o, colp/o ): intercourse, menstrual flow, birth canal; placenta ( placent/o ): nutrient and waste exchange."],"dp":[]},"term1-repro:e3":{"s":1,"u":["Uterine layers: perimetrium, myometrium, endometrium.","Uterine layers: perimetrium (outer), myometrium (muscular middle), endometrium (inner)."],"dp":[{"h":"Why the uterus has three roots","t":"Hyster/o is Greek (hysterectomy), metr/o and metri/o are also Greek (endometrium, metrorrhagia), and uter/o is Latin (uterine). Each tends to appear in particular words, so recognising all three lets you decode surgery names, tissue layers and bleeding disorders alike. Source: the lecture's structures and combining forms table."}]},"term1-repro:e4":{"s":1,"u":["-gravida pregnant; -para give birth; nulligravida vs nullipara.","Other word parts: -gravida pregnant; gynec/o woman; mast/o breast; men/o menstruation; ov/o egg; -para to give birth; -pexy surgical fixation."],"dp":[{"h":"Why -gravida and -para are counted separately","t":"A woman may have been pregnant without giving birth (miscarriage), so obstetric history records pregnancies (gravida) and births (para) separately. Nulligravida and nullipara are the starting points of that count. Source: the lecture's word parts list."}]},"term1-repro:e5":{"s":2,"u":["men/o menstruation: menarche, oligomenorrhea, menometrorrhagia."],"dp":[]},"term1-repro:e6":{"s":2,"u":["mast/o breast: mastalgia, mastopexy (-pexy = fixation).","Endometriosis , epididymitis , episiotomy (incision of the perineum at birth), galactorrhea (milk flow), gonorrhea , haematospermia (blood in semen), hydrocele , hypomenorrhea and oligomenorrhea (scanty/infrequent periods), menometrorrhagia (excessive bleeding during and between periods), metrorrhea , leukorrhea (whitish discharge), hysterectomy , hysteroscopy , hysterosalpingography , mastalgia (breast pain), mastopexy (breast lift), menarche (first period), perimenopause , neonate (newborn), nulligravida (never pregnant), nullipara (never given birth), oophorectomy , orchidectomy , orchiopexy (fixing an undescended testis), ovariorrhexis (rupture of an ovary), fibroadenoma, fibrocystic breast disease."],"dp":[]},"term1-repro:e7":{"s":2,"u":["Orchiopexy fixes an undescended testis; oophorectomy removes an ovary.","Endometriosis , epididymitis , episiotomy (incision of the perineum at birth), galactorrhea (milk flow), gonorrhea , haematospermia (blood in semen), hydrocele , hypomenorrhea and oligomenorrhea (scanty/infrequent periods), menometrorrhagia (excessive bleeding during and between periods), metrorrhea , leukorrhea (whitish discharge), hysterectomy , hysteroscopy , hysterosalpingography , mastalgia (breast pain), mastopexy (breast lift), menarche (first period), perimenopause , neonate (newborn), nulligravida (never pregnant), nullipara (never given birth), oophorectomy , orchidectomy , orchiopexy (fixing an undescended testis), ovariorrhexis (rupture of an ovary), fibroadenoma, fibrocystic breast disease."],"dp":[]}},"meta":{"9dup56":{"a":"relationship","vg":"term1-repro:e0/relationship/1"},"1ujrb1w":{"a":"recall","vg":"term1-repro:e1/recall/1"},"1ngf2lv":{"a":"recall","vg":"term1-repro:e2/recall/1"},"16a5frc":{"a":"recall","vg":"term1-repro:e2/recall/2"},"iqyjo9":{"a":"recall","vg":"term1-repro:e2/recall/1"},"qcqk9p":{"a":"recall","vg":"term1-repro:e3/recall/1"},"fue32v":{"a":"recall","vg":"term1-repro:e6/recall/1"},"x1z3p4":{"a":"recall","vg":"term1-repro:e6/recall/2"},"1u8lath":{"a":"recall","vg":"term1-repro:e6/recall/3"},"11c1xvm":{"a":"recall","vg":"term1-repro:e7/recall/1"},"pt0rb8":{"a":"recall","vg":"term1-repro:e7/recall/2"},"1jprl1p":{"a":"recall","vg":"term1-repro:e6/recall/4"},"1ch1obh":{"a":"recall","vg":"term1-repro:e6/recall/5"},"1k92lxj":{"a":"recall","vg":"term1-repro:e6/recall/6"},"1e769zn":{"a":"recall","vg":"term1-repro:e8/recall/1"}},"explRev":"6c39dabc9418"};
